import assert from "node:assert/strict";
import { test } from "node:test";
import { gitBlobId, hasFrontmatter, isSafeWorkflowEntry, lockEvidence, sortCandidates } from "./collect.mjs";

test("lockEvidence reads only the leading comment header", () => {
  assert.deepEqual(lockEvidence("# This file was automatically generated by gh-aw. DO NOT EDIT.\nname: x\n"), ["generated-header"]);
  assert.deepEqual(lockEvidence('# gh-aw-metadata: {"compiler_version":"v1.2.3"}\non: push\n'), ["gh-aw-metadata compiler_version=v1.2.3"]);
  assert.deepEqual(lockEvidence('# gh-aw-metadata: {"compiler_version":""}\n'), []);
  assert.deepEqual(lockEvidence("name: x\n# automatically generated by gh-aw\n"), []);
});

test("hasFrontmatter requires opening and closing delimiters", () => {
  assert.equal(hasFrontmatter("---\non: push\n---\nbody"), true);
  assert.equal(hasFrontmatter("---\r\non: push\r\n---\r\n"), true);
  assert.equal(hasFrontmatter("# README\n---\n"), false);
  assert.equal(hasFrontmatter("---\non: push\n"), false);
});

test("isSafeWorkflowEntry rejects symlinks, submodules, and unsafe names", () => {
  assert.equal(isSafeWorkflowEntry({ type: "blob", mode: "100644", path: "a.lock.yml" }), true);
  assert.equal(isSafeWorkflowEntry({ type: "blob", mode: "120000", path: "a.lock.yml" }), false);
  assert.equal(isSafeWorkflowEntry({ type: "commit", mode: "160000", path: "a.md" }), false);
  assert.equal(isSafeWorkflowEntry({ type: "blob", mode: "100644", path: "a b.md" }), false);
});

test("gitBlobId matches git hash-object", () => {
  assert.equal(gitBlobId(Buffer.from("hello\n")), "ce013625030ba8dba906f756967f9e9ca394464a");
});

test("sortCandidates orders by stars desc then name", () => {
  const out = sortCandidates([
    { full_name: "b/x", stars: 5 },
    { full_name: "A/y", stars: 5 },
    { full_name: "c/z", stars: 9 },
  ]);
  assert.deepEqual(out.map(c => c.full_name), ["c/z", "A/y", "b/x"]);
});
